function giveColorValueToSwatches() {
  const storedMC1 = localStorage.getItem("MC1");
  if (storedMC1 !== null) pickedMC1 = storedMC1;
  MC1pickerBtn.value = pickedMC1;

  const storedCC1 = localStorage.getItem("CC1");
  if (storedCC1 !== null) pickedCC1 = storedCC1;
  CC1pickerBtn.value = pickedCC1;

  const storedContrastMC1 = localStorage.getItem("contrastMC1");
  if (storedContrastMC1 !== null) pickedContrastMC1 = storedContrastMC1;
  contrastMC1PickerBtn.value = pickedContrastMC1;

  const storedContrastCC1 = localStorage.getItem("contrastCC1");
  if (storedContrastCC1 !== null) pickedContrastCC1 = storedContrastCC1;
  contrastCC1PickerBtn.value = pickedContrastCC1;
}

// accordions:
function accordions() {
  for (let i = 0; i < accArray.length; i++) {
    accArray[i].addEventListener("click", toggleAccordions);
  }
}

function toggleAccordions() {
  this.classList.toggle("active");
  let panel = this.nextElementSibling;
  if (panel.style.maxHeight && panel.style.maxHeight !== "0px") {
    panel.style.maxHeight = `0px`;
    if (panel.id == "socials") {
      panel.style.padding = "0px";
    }
  } else {
    panel.style.maxHeight = `${panel.scrollHeight}px`;
    if (panel.class == "intro") {
      panel.style.maxHeight = `${panel.scrollHeight + 2000}px`;
    }
    if (panel.id == "socials") {
      panel.style.padding = "16px";
      panel.style.maxHeight = `${panel.scrollHeight + 16}px`;
      document.getElementById("socials").focus();
    }
  }
}

// picking MC and CC:
function chooseMotifColors() {
  if (localStorage.MC1) {
    pickedMC1 = localStorage.MC1;
  } else {
    pickedMC1 = "#000080";
  }

  if (localStorage.CC1) {
    pickedCC1 = localStorage.CC1;
  } else {
    pickedCC1 = "#6f4d23";
  }

  /*   if (localStorage.letterColor) {
      pickedLetterColor = localStorage.letterColor;
    } else {
      pickedLetterColor = "#000000";
    } */
  updateHEXcodeDisplay(pickedMC1, pickedCC1);
  updateSVG_innerHTML();
  pickSVG();
}

function updateHEXcodeDisplay(pickedMC1, pickedCC1) {
  MC1hexDisplay.innerHTML = `hex: ${pickedMC1}`;
  CC1hexDisplay.innerHTML = `hex: ${pickedCC1}`;
}

function changeMC1() {
  pickedMC1 = MC1pickerBtn.value;
  updatePickedColors(pickedMC1, pickedCC1, pickedContrastMC1, pickedContrastCC1);
  localStorage_MC1();
}

function changeCC1() {
  pickedCC1 = CC1pickerBtn.value;
  updatePickedColors(pickedMC1, pickedCC1, pickedContrastMC1, pickedContrastCC1);
  localStorage_CC1();
}

function changeletterColor() {
  pickedContrastMC1 = contrastMC1PickerBtn.value
  pickedContrastCC1 = contrastCC1PickerBtn.value
  updatePickedColors(pickedMC1, pickedCC1, pickedContrastMC1, pickedContrastCC1);
  localStorage_contrastMC1()
  localStorage_contrastCC1()
}

function updatePickedColors(pickedMC1, pickedCC1, pickedContrastMC1, pickedContrastCC1) {
  MC1pickerBtn.value = pickedMC1;
  CC1pickerBtn.value = pickedCC1;
  contrastMC1PickerBtn.value = pickedContrastMC1;
  contrastCC1PickerBtn.value = pickedContrastCC1;

  updateHEXcodeDisplay(pickedMC1, pickedCC1);
  updateSVG_innerHTML();
  cleanSVGandBoxes();
}

function pickSVG() {
  /* console.log('function pickSVG()') */
  selectedMotif = motifPickerDropDown.value;
  if (!selectedMotif) {
    SVGinDiv.innerHTML = "";
    return;
  }
  determinarSVGcharacteristics(selectedMotif);
  viewBox = `0 0 ${svgOldWidth} ${svgOldHeight}`;
  calculateSVGWidth(svgWidth);
  updateSVG_innerHTML();
  drawSVG(selectedMotif);
}

function determinarSVGcharacteristics() {
  /*   console.log("🚀 ~ determinarSVGcharacteristics ~ selectedMotif:", selectedMotif)
    console.log(selectedMotif) */
  svgWidth = 900;
  svgHeight = 600;
  switch (selectedMotif) {
    /* SVG: */
    case "chevron":
      selectedMotif_innerHTML = chevron_innerHTML;
      break;
    case "inANDout":
      selectedMotif_innerHTML = inANDout_innerHTML;
      break;
    case "zigzag":
      selectedMotif_innerHTML = zigzag_innerHTML;
      break;
    case "bullseye":
      selectedMotif_innerHTML = bullseye_innerHTML;
      break;
    case "spiral":
      selectedMotif_innerHTML = spiral_innerHTML;
      break;
    case "diamonds":
      selectedMotif_innerHTML = diamonds_innerHTML;
      break;
    case "starter":
      selectedMotif_innerHTML = starter_innerHTML;
      break;
  }
  svgOldWidth = svgWidth;
  svgOldHeight = svgHeight;

}

function calculateSVGWidth(svgWidth) {
  viewportWidth = window.innerWidth;
  viewBox = `0 0 ${svgOldWidth} ${svgOldHeight}`;

  svgNewWidth = svgWidth;
  svgNewHeight = svgHeight;

  if (viewportWidth > viewportHeight) {
    if (viewportHeight < svgHeight) {
      svgNewHeight = viewportHeight * 0.9
      svgNewWidth = (svgNewHeight * svgWidth / svgHeight)
    }
  }
  if (viewportHeight > viewportWidth) {
    svgNewWidth = viewportWidth * 0.9
    svgNewHeight = (svgNewWidth * svgHeight / svgWidth)
  }

  svgWidth = svgNewWidth;
  svgHeight = svgNewHeight

}

function drawSVG(selectedMotif) {
  if (!selectedMotif) {
    SVGinDiv.innerHTML = "";
    return;
  }
  updateSVG_innerHTML();
  SVGinDiv.innerHTML = `<svg id= "${selectedMotif}_svg" width="${svgNewWidth}" height="${svgNewHeight}" viewBox="${viewBox}"
    style="border:1px solid var(--color4); background-color:#ffffff"> 
    ${selectedMotif_innerHTML}
    </svg>`;
  WovenMotifSVG.appendChild(SVGinDiv);
  document.getElementById("svgChartDiv").focus();
}

function createSVGwithBoxes() {
  selectedMotif = motifPickerDropDown.value;
  if (!selectedMotif) {
    SVGinDiv.innerHTML = "";
    return;
  }
  /* hideBtn(resetColorsDiv); */
  /* resetColorsDiv.remove();  */
  cleanSVGandBoxes();
  drawSVGwithBoxes();
  /* resetColorsDiv.remove();  */
}

function drawSVGwithBoxes() {
  selectedMotif = motifPickerDropDown.value;
  createSVG()
  document.getElementById("svgChartDiv").focus();
}

function createSVG() {
  if (!selectedMotif) {
    SVGinDiv.innerHTML = "";
    return;
  }
  SVGinDiv.innerHTML = `<svg id= "${selectedMotif}_svg" width="${svgNewWidth}" height="${svgNewHeight}" viewBox="${viewBox}"
    style="border:1px solid var(--color4); background-color:#ffffff"> 
    ${selectedMotif_innerHTML}
    </svg>`;
  WovenMotifSVG.appendChild(SVGinDiv);
  SVGDiv.classList.add("grid");
}

